"""
Spirit Board Python Library

This library provides a Python interface for communicating with the Spirit Board
invoker firmware running on an ESP32. The Spirit Board is used to communicate
with Furby toys over their proprietary serial bus.

Author: Renegade Science
"""

import socket
import re
from typing import Tuple, List, Optional


class SpiritBoard:
    """
    A high-level interface for controlling the Spirit Board invoker firmware.

    The Spirit Board acts as a bridge between modern computers and the Furby
    serial bus, allowing you to send commands and control motor operations.

    Attributes:
        host (str): IP address of the ESP32 running the invoker firmware
        port (int): TCP port number (default: 5000)
        timeout (float): Socket timeout in seconds (default: 5.0)
    """

    DEFAULT_PORT = 5000
    DEFAULT_TIMEOUT = 5.0

    def __init__(self, host: str, port: int = DEFAULT_PORT, timeout: float = DEFAULT_TIMEOUT):
        """
        Initialize a Spirit Board connection.

        Args:
            host: IP address of the ESP32 (e.g., "192.168.1.100")
            port: TCP port number (default: 5000)
            timeout: Socket timeout in seconds (default: 5.0)
        """
        self.host = host
        self.port = port
        self.timeout = timeout

    def send_hex_command(self, hex_string: str) -> str:
        """
        Send a single hex command to the invoker firmware and return the response.

        This is the low-level command interface. Most users should use the
        higher-level methods like ping(), init_coprocessor(), etc.

        Args:
            hex_string: String containing hex digits (whitespace will be stripped)

        Returns:
            The entire response decoded as ASCII

        Raises:
            ValueError: If hex_string contains invalid characters
            socket.timeout: If the connection times out with no response
        """
        # Remove all whitespace so the firmware only sees hex digits
        cleaned = "".join(hex_string.split())
        if not cleaned:
            raise ValueError("hex_string must contain at least one hex digit")

        # Basic validation: all characters must be hex
        for ch in cleaned:
            if ch not in "0123456789abcdefABCDEF":
                raise ValueError(f"Invalid hex character {ch!r} in {hex_string!r}")

        data = (cleaned + "\n").encode("ascii")

        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(self.timeout)
            s.connect((self.host, self.port))
            s.sendall(data)

            chunks = []
            while True:
                try:
                    chunk = s.recv(1024)
                except socket.timeout:
                    # If we've already got something, return it; otherwise, report timeout
                    if chunks:
                        break
                    return "[NO RESPONSE - socket timeout]"
                if not chunk:
                    break
                chunks.append(chunk)

        resp = b"".join(chunks)
        return resp.decode("ascii", errors="replace").strip()

    def ping(self) -> str:
        """
        Ping the invoker firmware to verify connectivity.

        Returns:
            The ASCII string '31337' if the firmware is responding correctly
        """
        # Control byte 0xFF, no payload
        return self.send_hex_command("FF")

    def init_coprocessor(self) -> str:
        """
        Pulse /INIT low for 10 ms to reset the Furby coprocessor.

        This should be called before sending command sequences to ensure
        the Furby is in a known state.

        Returns:
            Firmware status string
        """
        # Control byte 0x01, no payload required
        return self.send_hex_command("01")

    def send_nibble_stream(self, nibble_hex: str) -> str:
        """
        Send an arbitrary nibble stream to the Furby bus.

        Each character in nibble_hex represents a 4-bit nibble that will be
        sent over the Furby serial bus. This is the primary method for
        sending commands to make the Furby perform actions.

        Args:
            nibble_hex: String of hex digits representing successive 4-bit nibbles
                       (e.g., "F7F347F7F71C000000000000F000FFFFFF")

        Returns:
            Firmware response including nibble echo and timing information
        """
        # Control byte 0x02 + nibble payload
        return self.send_hex_command("02" + nibble_hex)

    def _format_duration_us(self, duration_us: int) -> str:
        """
        Format a duration in microseconds as a 16-hex-digit big-endian 64-bit value.

        Args:
            duration_us: Duration in microseconds (non-negative)

        Returns:
            16 uppercase hex digits (e.g., 1_000_000 -> '00000000000F4240')

        Raises:
            ValueError: If duration_us is negative
        """
        if duration_us < 0:
            raise ValueError("duration_us must be non-negative")
        # Mask to 64 bits and format as 16 uppercase hex digits
        return f"{int(duration_us) & ((1 << 64) - 1):016X}"

    def motor_forward(self, duration_us: int) -> str:
        """
        Drive the Furby motor forward for a specified duration.

        Args:
            duration_us: Duration in microseconds (e.g., 1_000_000 for 1 second)

        Returns:
            Firmware response
        """
        payload = self._format_duration_us(duration_us)
        # Control byte 0x03 + 64-bit duration payload
        return self.send_hex_command("03" + payload)

    def motor_backward(self, duration_us: int) -> str:
        """
        Drive the Furby motor backward for a specified duration.

        Args:
            duration_us: Duration in microseconds (e.g., 1_000_000 for 1 second)

        Returns:
            Firmware response
        """
        payload = self._format_duration_us(duration_us)
        # Control byte 0x04 + 64-bit duration payload
        return self.send_hex_command("04" + payload)

    def get_rts_timing(self) -> str:
        """
        Read the RTS timing register from the firmware.

        This returns detailed timing information about the /RTS signal during
        the last nibble stream transmission. Useful for debugging and analysis.

        Returns:
            RTS timing data as a string
        """
        # Control byte 0x05, no payload
        return self.send_hex_command("05")


def parse_nibble_echo(response: str) -> Tuple[int, List[int]]:
    """
    Parse a firmware response containing a nibble echo.

    The firmware responds with a line like:
        [NIBBLES] count=24 : 7,F,3,4,1,F,...

    This function extracts the count and nibble values from that response.

    Args:
        response: Firmware response string

    Returns:
        Tuple of (count, list of nibble values as integers)

    Raises:
        ValueError: If the response doesn't contain a valid [NIBBLES] line

    Example:
        >>> parse_nibble_echo("[NIBBLES] count=4 : F,7,3,4")
        (4, [15, 7, 3, 4])
    """
    lines = response.splitlines()
    nib_line = None
    for line in lines:
        if line.startswith("[NIBBLES]"):
            nib_line = line
            break
    if nib_line is None:
        raise ValueError(f"No [NIBBLES] line found in response: {response!r}")

    # Rough parse: extract the 'count=' number and the stuff after ':'
    m = re.search(r"count\s*=\s*(\d+)\s*:\s*(.*)", nib_line)
    if not m:
        raise ValueError(f"Could not parse [NIBBLES] line: {nib_line!r}")

    count = int(m.group(1))
    tail = m.group(2).strip()

    nibs = []
    if tail:
        for part in tail.split(","):
            part = part.strip()
            if not part:
                continue
            # Interpret as hex (so 'F' -> 15, '0' -> 0, 'A' -> 10, etc.)
            nibs.append(int(part, 16))

    return count, nibs


# Predefined Furby command sequences
# These are known command sequences captured from actual Furby communication
FURBY_COMMANDS = {
    "init": "F7F347F7F71C000000000000000000000000F000FFFFFF",

    "yawn": "",

    "sequence-0": "",

    "me": "",

    "mee-mee": "",

    "cockadoodledoo": "",

    "giggle": "",

    "peek-boo-kiss": "",

    "sequence-1": "",

    "sequence-2": "",

    "sequence-3": "",

    "sequence-4": "",

    "sequence-5": "",

    "sequence-6": "",

    "sequence-7": "",

    "sequence-8": "",

    "sequence-9": "",

    "sequence-10": "",

    "sequence-11": "",

    "sequence-12": "",

}


def get_furby_command(command_name: str) -> Optional[str]:
    """
    Get a predefined Furby command sequence by name.

    Args:
        command_name: Name of the command (e.g., "init", "yawn", "giggle")

    Returns:
        Hex string for the command, or None if not found

    Example:
        >>> cmd = get_furby_command("init")
        >>> board.send_nibble_stream(cmd)
    """
    return FURBY_COMMANDS.get(command_name.lower())


def list_furby_commands() -> List[str]:
    """
    Get a list of all available predefined Furby command names.

    Returns:
        List of command names
    """
    return sorted(FURBY_COMMANDS.keys())
